<script setup lang="ts">import {ref} from 'vue';import {readUser,clear} from './stores/session';import {useWorkspace} from './hooks/useWorkspace';import {navigation} from './router/navigation';import {ROLES} from './constants/enums';import Login from './pages/Login.vue';import Overview from './pages/Overview.vue';import Datasets from './pages/Datasets.vue';import Arcs from './pages/Arcs.vue';import Scenarios from './pages/Scenarios.vue';import Results from './pages/Results.vue';import Reviews from './pages/Reviews.vue';import Notice from './components/common/Notice.vue';const user=ref(readUser()),page=ref(location.hash.slice(1)||'overview');const {data,error,loading,refresh}=useWorkspace(user);function go(value:string){page.value=value;location.hash=value;window.scrollTo(0,0)}function logout(){clear();user.value=null};</script><template><Login v-if="!user" @login="user=$event"/><div v-else class="shell"><aside class="side-atlas"><a class="brand" href="#overview" @click="go('overview')"><span>衡</span><div>衡远联运<small>中转网络韧性推演</small></div></a><div class="contents-label">NETWORK ATLAS / 2026</div><nav><button v-for="n in navigation" :key="n.id" :class="{active:page===n.id}" @click="go(n.id)"><i>{{n.code}}</i>{{n.label}}<b>↗</b></button></nav><div class="side-bottom"><span>模拟拓扑 / 离线规划</span><p>容量有界，<br/>流量守恒。</p><small>{{ROLES[user.role]}}</small><button @click="logout">退出图册</button></div></aside><main class="workspace"><div class="topline"><span>HENGYUAN / CAPACITY & REACHABILITY</span><span>{{user.email}}</span></div><Notice v-if="error" error>{{error}}<button class="text-button" @click="refresh">重试</button></Notice><p v-if="loading">正在读取网络图册…</p><template v-else><Overview v-if="page==='overview'" :data="data" @go="go"/><Datasets v-else-if="page==='datasets'" :data="data" :can-write="user.role!=='viewer'" :refresh="refresh"/><Arcs v-else-if="page==='arcs'" :data="data" :can-write="user.role!=='viewer'" :refresh="refresh"/><Scenarios v-else-if="page==='scenarios'" :data="data" :can-write="user.role!=='viewer'" :refresh="refresh" @go="go"/><Results v-else-if="page==='results'" :data="data"/><Reviews v-else :data="data" :can-write="user.role!=='viewer'" :is-admin="user.role==='admin'" :refresh="refresh"/></template><footer>衡远联运 · 模拟中转网络<span>容量 / 最小割 / 独立最短路</span></footer></main></div></template>
